-- 300 косметических продуктов: Arnest (Deonica, Dock Land) + Nivea, Natura Siberica, L'Oreal, Garnier и др.
-- Источник: Open Beauty Facts. Запускать после import_to_supabase.sql

ALTER TABLE products ADD COLUMN IF NOT EXISTS product_name TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS ingredients TEXT;


ON CONFLICT (barcode) DO UPDATE SET
  product_name = COALESCE(EXCLUDED.product_name, products.product_name),
  ingredients = COALESCE(EXCLUDED.ingredients, products.ingredients);

